// ============================================================================
// GPIO_apb: APB4 register wrapper around GPIO_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/GPIO.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/GPIO.md
// ============================================================================
module GPIO_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  inout tri [7:0] gpio
);
  localparam logic [31:0] ID_VALUE = 32'h47500200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [7:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd8) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & (~|hit | (PWRITE & (PSTRB != 4'hF) & (hit[6])));   // core registers take whole words

  // ---------------- core ----------------
  logic          c_wen;
  logic [7:0]    c_wdata;
  logic          c_ren;
  logic [7:0]    c_rdata;
  logic [7:0]    c_gpio_oe;
  logic          c_irq;
  GPIO_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .wen(c_wen),
    .waddr((wr ? ((hit[6] ? 4'd0 : 4'd0)) : 4'd0)),
    .wdata(c_wdata),
    .ren(c_ren),
    .raddr((rd ? ((hit[6] ? 4'd1 : 4'd0) | (hit[7] ? 4'd0 : 4'd0)) : 4'd0)),
    .rdata(c_rdata),
    .gpio(gpio),
    .gpio_oe(c_gpio_oe),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [7:0] r_OE;   // 12'h014 OE

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_OE <= 8'h0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_OE <= (r_OE & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
    end
  end

  // ---------------- core inputs ----------------
  assign c_gpio_oe = r_OE[7:0];
  // CORE: the core's register port (indices on the instance)
  assign c_wen = wr & (PSTRB == 4'hF) & (hit[6]);
  assign c_wdata = PWDATA[7:0];
  assign c_ren = rd & (hit[6] | hit[7]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(r_OE);
      10'd6: rdata = 32'(c_rdata);
      10'd7: rdata = 32'(c_rdata);
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
